from pathlib import Path
import re,json
R=Path(__file__).resolve().parents[1]
def write(p,s):
    p=R/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
header='''<header class="ca-header"><a class="ca-brand" href="index.html" aria-label="クルーアセント ホーム"><img src="assets/brand/logo-mark.svg" width="42" height="42" alt=""><span>CREW ASCENT<small>クルーアセント</small></span></a><nav class="ca-nav" aria-label="メインナビゲーション"><a href="services.html">サービス</a><a href="plans.html">プラン・料金</a><a href="types.html">36のサイトタイプ</a><a href="about.html">私たちについて</a></nav><a class="ca-header-cta" href="contact.html">無料で相談する <span aria-hidden="true">↗</span></a><details class="ca-menu"><summary>メニュー</summary><nav aria-label="モバイルナビゲーション"><a href="services.html">サービス</a><a href="plans.html">プラン・料金</a><a href="diagnosis.html">Web診断36</a><a href="types.html">36タイプ一覧</a><a href="process.html">制作の流れ</a><a href="management.html">公開・管理</a><a href="about.html">私たちについて</a><a href="guide.html">ガイド</a><a href="faq.html">よくある質問</a><a href="contact.html">無料ヒアリングシート</a><a href="booking.html">相談日時を予約する</a></nav></details></header>'''
footer='''<footer class="ca-footer"><div class="wrap"><div class="ca-footer-top"><div><a class="ca-wordmark" href="index.html">CREW ASCENT<span>クルーアセント</span></a><p>決める前に、整理するところから。</p></div><div class="ca-footer-links"><a href="services.html">Webサイト制作</a><a href="plans.html">プラン・料金</a><a href="diagnosis.html">Web診断36</a><a href="process.html">制作の流れ</a><a href="types.html">36タイプ一覧</a><a href="management.html">公開・管理</a><a href="guide.html">制作ガイド</a><a href="works.html">制作例・見本</a><a href="faq.html">よくある質問</a><a href="contact.html">無料相談</a><a href="booking.html">相談予約</a><a href="contracts.html">契約書・お支払い</a></div></div><div class="ca-footer-bottom"><span>© <span data-year>2026</span> CREW ASCENT</span><div><a href="privacy.html">プライバシー</a><a href="terms.html">利用規約</a><a href="commercial-transactions.html">特定商取引法に基づく表記</a></div></div></div></footer>'''
def page(title,desc,body,js=''):
    return f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}｜クルーアセント</title><meta name="description" content="{desc}"><meta name="robots" content="noindex,follow"><meta name="theme-color" content="#10243a"><link rel="icon" href="assets/brand/icon-32.png"><link rel="stylesheet" href="assets/css/base.css"><link rel="stylesheet" href="assets/css/upgrade.css"><script defer src="assets/js/upgrade.js"></script>{js}</head><body class="ca-page"><a class="skip-link" href="#main">本文へスキップ</a>{header}<main id="main">{body}</main>{footer}</body></html>'''
def intro(label,title,desc):
    return f'<section class="ca-intro wrap"><p class="ca-kicker">{label}</p><h1>{title}</h1><p class="ca-intro-lead">{desc}</p></section>'
def cta():
    return '''<section class="ca-cta"><div class="wrap ca-cta-inner"><div><p class="ca-kicker">LET’S FIND YOUR DIRECTION</p><h2>まだ、まとまっていなくても。<br>そこから一緒に考えます。</h2><p>相談は無料。制作するかどうかは、内容を確認してから決められます。</p></div><div><a class="ca-button ca-button-white" href="contact.html">無料ヒアリングシートへ <span>↗</span></a><a class="ca-text-link" href="booking.html">話しながら整理したい方は、60分の相談予約へ →</a></div></div></section>'''
old=(R/'index.html').read_text(encoding='utf-8')
diagnosis=re.search(r'<section class="sec sec--tint-1" id="diagnosis">[\s\S]*?</section>',old).group()
diagnosis=diagnosis.replace('マスを選ぶと、そのタイプの名前が出ます。タイプに優劣はありません。','4問で方向を試してみることも、36タイプを眺めることも。気になる入口からどうぞ。')
for f in R.glob('*.html'):
    s=f.read_text(encoding='utf-8')
    s=re.sub(r'<header\b[\s\S]*?</header>',header,s,count=1)
    s=re.sub(r'<footer\b[\s\S]*?</footer>',footer,s,count=1)
    s=re.sub(r'<div class="mcta"[\s\S]*?</div>','',s)
    s=s.replace('</head>','<link rel="stylesheet" href="assets/css/upgrade.css"><script defer src="assets/js/upgrade.js"></script></head>')
    s=s.replace('data-form-link','data-native-form-link').replace('aria-disabled="true"','')
    s=re.sub(r'href="#"(?=[^>]*data-native-form-link)', 'href="contact.html"',s)
    s=re.sub(r'data-native-form-link([^>]*?)href="[^"]*"',r'data-native-form-link\1href="contact.html"',s)
    s=re.sub(r'<script[^>]*src="assets/js/scroll-steady.js[^>]*></script>','',s)
    write(f.name,s)
plans=[
dict(id='first',name='はじめて',price=80000,pages='1ページ',copy='まずは、事業の窓口を。',text='支給原稿の誤字・見出しを調整',images='原則、ご支給の画像を使用',revisions='1回',weeks='1〜2週間'),
dict(id='simple',name='シンプル',price=120000,pages='3ページ前後',copy='必要な情報を、すっきり。',text='フォーム回答をもとに文章を整理',images='商用利用可能な素材を簡易準備',revisions='1〜2回',weeks='2〜3週間'),
dict(id='standard',name='標準',price=150000,pages='5ページ前後',copy='事業の全体像を、きちんと。',text='ページ構成に合わせて文章を整理',images='ページごとに素材を選定・調整',revisions='1〜2回',weeks='3〜4週間'),
dict(id='omakase',name='おまかせ',price=220000,pages='5ページ前後＋準備支援',copy='伝える準備から、一緒に。',text='回答から見出し・紹介文・導線文を作成',images='画像準備＋簡易ロゴ1案',revisions='1〜3回',weeks='4〜6週間')]
write('data/commerce-plans.json',json.dumps(plans,ensure_ascii=False,indent=2))
def cards():
    return '<div class="ca-plan-grid">'+''.join(f'''<article class="ca-plan" id="plan-{p['id']}"><span class="ca-kicker">PLAN 0{i+1}</span><h3>{p['name']}</h3><p>{p['copy']}</p><div class="ca-price">{p['price']:,}<small>円</small></div><p class="ca-tax">税区分は公開前に確定</p><dl><div><dt>構成</dt><dd>{p['pages']}</dd></div><div><dt>文章</dt><dd>{p['text']}</dd></div><div><dt>画像</dt><dd>{p['images']}</dd></div><div><dt>修正</dt><dd>{p['revisions']}</dd></div><div><dt>納期</dt><dd>{p['weeks']}</dd></div></dl><a class="ca-button ca-button-line" href="contact.html?plan={p['id']}">このプランを相談する <span>↗</span></a><a class="ca-plan-payment" href="checkout-{p['id']}.html">契約・支払い内容を確認 →</a></article>''' for i,p in enumerate(plans))+'</div>'
home='''<section class="ca-hero"><div class="wrap ca-hero-grid"><div class="ca-hero-copy"><p class="ca-kicker"><span class="ca-live-dot"></span> SMALL BUSINESS, THOUGHTFULLY DESIGNED.</p><h1>あなたの事業を、<br><em>伝わる</em>かたちに。</h1><p class="ca-hero-statement">決める前に、整理するところから。</p><p class="ca-hero-lead">何を載せるか、どう見せるか。<br>Web診断36とヒアリングで方向を見つけ、<br>今の事業に必要なWebサイトをつくります。</p><div class="ca-actions"><a class="ca-button" href="diagnosis.html">無料で、方向を見つける <span>↗</span></a><a class="ca-text-link" href="plans.html">4つのプランを見る <span>→</span></a></div><p class="ca-reassurance">診断は登録不要 <span>／</span> 結果を見るだけでも大丈夫</p></div><div class="ca-hero-visual"><img src="assets/img/web-planning-workspace-1000.webp" alt="Webサイトの構成や素材を整理する作業イメージ" width="1000" height="750" fetchpriority="high"><div class="ca-visual-label"><span>FROM YOUR BUSINESS<br>TO YOUR WEBSITE.</span><span>01 — 36</span></div><a class="ca-hero-map" href="types.html"><div class="ca-map-geometry" aria-hidden="true">'''+''.join(f'<i class="cell-{i//6}-{i%6}"></i>' for i in range(36))+'''</div><div><span class="ca-kicker">WEB DIAGNOSIS 36</span><strong>「好き」の先に、<br>事業に合う方向がある。</strong><span>36のサイトタイプを見てみる ↗</span></div></a></div></div><div class="wrap ca-hero-baseline"><span>WEB DESIGN & DEVELOPMENT</span><span>診断 → 設計 → 制作 → 公開</span><a href="#diagnosis">EXPLORE ↓</a></div></section><section class="ca-promise wrap"><p>小さな事業の、<br><strong>大切な一歩のために。</strong></p><div><span class="ca-kicker">01 / UNDERSTAND</span><h2>目的から、考える。</h2><p>見た目を決める前に、誰に何を伝えるかを整理します。</p></div><div><span class="ca-kicker">02 / MAKE IT CLEAR</span><h2>範囲と料金を、明確に。</h2><p>4つのプランを同じ条件で比較。追加作業は事前に確認します。</p></div><div><span class="ca-kicker">03 / AT YOUR PACE</span><h2>あなたのペースで。</h2><p>文章での相談も、60分の対話も。進め方を選べます。</p></div></section>'''+diagnosis+'''<section class="ca-section wrap"><div class="ca-section-head"><div><p class="ca-kicker">DESIGN WITH A REASON</p><h2>整えるのは、見た目と、<br>その先の使いやすさ。</h2></div><p>事業の説明から、問い合わせまで。<br>ひとつずつ、迷わずたどれるように。</p></div><div class="ca-feature-grid"><figure><img src="assets/img/copy-organization-workflow-900.webp" alt="情報を整理しページ構成に落とし込む制作イメージ" width="900" height="600" loading="lazy"><figcaption>01 / CONTENT & STRUCTURE<h3>言いたいことを、伝わる順番へ。</h3><p>サービス、料金、選ばれる理由。読み手が知りたい順番で、ページと文章を組み立てます。</p></figcaption></figure><figure><img src="assets/img/production-readiness-overview-900.webp" alt="公開前にWebサイトを確認する制作イメージ" width="900" height="600" loading="lazy"><figcaption>02 / EXPERIENCE & DELIVERY<h3>見つけやすく、使いやすく。</h3><p>スマートフォンでの読みやすさ、相談への導線、検索に内容を伝える基本設定まで整えます。</p></figcaption></figure></div><a class="ca-text-link" href="services.html">制作で行うこと・行わないことを見る →</a></section><section class="ca-section ca-plan-section"><div class="wrap"><div class="ca-section-head"><div><p class="ca-kicker">FOUR WAYS TO START</p><h2>必要な範囲を、選べる。</h2></div><p>ページ数と、文章・画像の準備範囲で選ぶ4プラン。<br>どのプランにも、スマホ対応と基本SEOを含みます。</p></div>'''+cards()+'''<p class="ca-fine">制作費は買い切り。公開・管理は任意の別契約です。納期は素材の提出後から。複雑な予約・決済機能は別途お見積もりします。</p><a class="ca-text-link" href="plans.html">含まれる内容と追加費用を詳しく見る →</a></div></section><section class="ca-section wrap"><div class="ca-section-head"><div><p class="ca-kicker">A CLEAR PROCESS</p><h2>相談から公開まで、<br>次の一歩が見える。</h2></div><a class="ca-text-link" href="process.html">制作の流れを詳しく →</a></div><ol class="ca-process"><li><span>01</span><h3>整理する</h3><p>診断や無料相談で、ご希望と必要な情報を整理。</p></li><li><span>02</span><h3>確かめる</h3><p>作業範囲・金額・納期を確認して、契約と着手金のお支払い。</p></li><li><span>03</span><h3>つくる</h3><p>原稿・画像をもとに制作。初稿をご確認いただき、修正へ。</p></li><li><span>04</span><h3>届ける</h3><p>最終確認と残金のお支払い後に、公開または納品。</p></li></ol></section><section class="ca-section ca-faq-section"><div class="wrap ca-faq-grid"><div><p class="ca-kicker">BEFORE WE BEGIN</p><h2>気になること、<br>先にお答えします。</h2><a class="ca-text-link" href="faq.html">すべての質問を見る →</a></div><div class="ca-faq"><details><summary>何も決まっていなくても相談できますか？</summary><p>はい。事業内容と「今、困っていること」からお聞かせください。必要なページや準備するものを一緒に整理します。</p></details><details><summary>診断を受けたら、申し込みが必要ですか？</summary><p>いいえ。診断は無料・登録不要で、結果だけの利用もできます。制作の申し込みや契約にはつながりません。</p></details><details><summary>オンラインで話す必要はありますか？</summary><p>必須ではありません。ヒアリングシートとメールだけでも相談できます。話しながら整理したい場合は、60分の相談枠を予約できます。</p></details><details><summary>制作費以外にも費用はかかりますか？</summary><p>ドメイン・サーバーなどの公開環境に費用がかかります。公開・管理プランは任意の別契約です。追加制作や外部サービス費は契約前に確認します。</p></details></div></div></section>'''+cta()
home_page=page('小規模事業者のためのWebサイト制作・Web診断36','診断とヒアリングで事業に合う方向を整理。4つの制作プランと、無料相談・60分予約をご用意しています。',home,'<link rel="stylesheet" href="assets/css/system.css"><link rel="stylesheet" href="assets/css/top.css"><script defer src="assets/js/top.js"></script>')
home_page=home_page.replace('</head>','<link rel="stylesheet" href="assets/css/upgrade.css"></head>').replace('<body class="ca-page">','<body class="ca-page ca-home">')
og=re.search(r'<meta property="og:image"[^>]+>',old)
if og:home_page=home_page.replace('</head>',og.group()+'</head>')
write('index.html',home_page)
